parameters.jsCode:
// Lee la pestana `Reservas` tal como esta escrita y la deja lista para la base.
//
// Las columnas, en el orden en que las creo `scripts/preparar-excel.js`:
//   A anotado_en  B fecha_evento  C fecha_legible  D sede  E cliente
//   F telefono_contacto  G origen  H google_event_id  I cancelada  J sincronizado
//
// Aqui NO se decide nada de la agenda: de eso se encarga
// `fn_sincronizar_agenda_desde_hoja`. Aqui solo se leen las celdas, se
// normaliza la fecha y se apartan las filas que no hay ni que intentar. Lo que
// no se entiende viaja con un `motivo` en vez de tirarse: asi el rechazo sale
// por el mismo sitio que los demas y acaba escrito al lado de su fila, que es
// la unica forma de que alguien lo vea.

const FECHA = 1, SEDE = 3, CLIENTE = 4, TELEFONO = 5, ORIGEN = 6, CANCELADA = 8, SINCRONIZADO = 9;

// Lo que cuenta como "libera esta fecha". Cualquier otra cosa se rechaza en
// vez de interpretarse: una celda que diga "ojo, preguntar a Diana" no puede
// acabar poniendo a la venta un sabado ya vendido.
const CANCELA = new Set(['si', 'sí', 'x', 'cancelada', 'cancelado',
                         'anulada', 'anulado', 'liberar', 'libre']);

const dosDigitos = (n) => String(n).padStart(2, '0');

// La fecha, venga como venga.
//
// Con valueRenderOption=UNFORMATTED_VALUE una fecha DE VERDAD llega como el
// numero de serie de Sheets -- dias desde el 30/12/1899 -- y ahi no hay
// ambiguedad posible. Si llega como texto es que se tecleo con la celda en
// formato texto, y entonces si hay que adivinar: 3/5/2027 se lee como 3 de
// mayo, que es como se escribe la fecha en Colombia. Por eso lo sano es
// escribirla como fecha y dejar que la hoja la formatee.
function fechaDe(v) {
  if (typeof v === 'number' && Number.isFinite(v)) {
    const ms = Date.UTC(1899, 11, 30) + Math.round(v) * 86400000;
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v === null || v === undefined ? '' : v).trim();
  let m;
  if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/))) return `${m[1]}-${dosDigitos(m[2])}-${dosDigitos(m[3])}`;
  if ((m = s.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})$/))) return `${m[1]}-${dosDigitos(m[2])}-${dosDigitos(m[3])}`;
  if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/))) return `${m[3]}-${dosDigitos(m[2])}-${dosDigitos(m[1])}`;
  return null;
}

const valores = ($input.first().json.values) || [];
const filas = [];
let saltadas = 0;

for (let i = 0; i < valores.length; i++) {
  const f = valores[i] || [];
  const fila = i + 2;                    // se leyo desde A2: la 1 es el encabezado
  const cel = (n) => (f[n] === undefined || f[n] === null) ? '' : String(f[n]).trim();

  const sede = cel(SEDE);
  const marca = cel(CANCELADA).toLowerCase();

  // Filas sin nada que sincronizar: las vacias y las que solo llevan una nota
  // suelta en alguna columna.
  if (!sede && !cel(FECHA)) { saltadas++; continue; }

  // Las del bot ya estan en la base por definicion: las escribio el nodo
  // `Anotar en Excel` DESPUES de insertarlas. Volver a mirarlas cada quince
  // minutos no arregla nada y llenaria la columna de la derecha de ruido. La
  // excepcion es una marcada como cancelada: eso si hay que mirarlo, aunque
  // sea para decir que desde aqui no se toca.
  if (cel(ORIGEN).toLowerCase().startsWith('bot') && !marca) { saltadas++; continue; }

  const item = {
    fila,
    sede,
    cliente: cel(CLIENTE),
    telefono: cel(TELEFONO),
    cancelar: false,
    motivo: null,
    fecha: null,
    // Lo que las columnas `origen` y `sincronizado` dicen AHORA. Viajan para
    // poder escribir de vuelta solo las celdas que de verdad cambian.
    origen_actual: cel(ORIGEN),
    nota_actual: cel(SINCRONIZADO),
  };

  if (marca) {
    if (CANCELA.has(marca)) item.cancelar = true;
    else item.motivo = `no entiendo "${cel(CANCELADA)}" en la columna cancelada: escribe "sí" o déjala vacía`;
  }

  item.fecha = fechaDe(f[FECHA]);
  if (!item.motivo && !item.fecha) item.motivo = `no entiendo la fecha "${cel(FECHA)}"`;

  filas.push(item);
}

// Sin filas que mirar no hay nada que preguntarle a la base, y devolver cero
// items corta el resto del workflow sin tocar nada.
if (!filas.length) return [];

return [{ json: { filas, leidas: valores.length, saltadas, procesadas: filas.length } }];

// La columna `sincronizado` de la hoja: que paso con cada fila, escrito al
// lado de la fila que lo provoco.
//
// Es el UNICO sitio donde se ven los rechazos -- no hay nadie mirando los logs
// de n8n -- asi que el texto tiene que aguantar leerse sin contexto.
//
// Y tiene que ser ESTABLE: se calcula solo a partir del estado de ahora, sin
// fechas ni horas dentro, para que dos corridas seguidas sin novedad escriban
// exactamente lo mismo. Abajo solo se manda lo que cambia, asi que en regimen
// esta rama no escribe ni una celda y la hoja no se llena de versiones.
//
// Una fila que se queda SIN nota es la senal de que la sincronizacion no la
// esta viendo: o esta vacia, o es del bot, o el workflow no llego hasta ella.

const filas = $('Leer Filas').first().json.filas;
const porFila = new Map(filas.map(f => [f.fila, f]));

const nota = (r) => {
  if (r.resultado === 'liberada') return '✓ liberada';
  if (r.resultado === 'omitida' && r.detalle === 'ya estaba liberada') return '✓ liberada';
  if (r.resultado === 'nueva' || r.resultado === 'reactivada' || r.resultado === 'ya estaba') {
    return '✓ en la agenda';
  }
  if (r.resultado === 'omitida') return '· ' + r.detalle;
  if (r.resultado === 'choque')  return '⚠ ' + r.detalle;
  return '✗ ' + r.detalle;
};

// Las que acabaron dentro de la agenda. Son las que pueden rellenar `origen`.
const ACEPTADAS = new Set(['nueva', 'reactivada', 'ya estaba']);

const data = [];
for (const item of $('Sincronizar').all()) {
  const r = item.json;
  const f = porFila.get(r.fila);
  if (!f) continue;                      // la fila viaja de ida y vuelta: no deberia faltar

  const texto = nota(r);
  if (texto !== f.nota_actual) data.push({ range: `Reservas!J${r.fila}`, values: [[texto]] });

  // Una fila escrita a mano llega sin `origen`. Se rellena una sola vez, para
  // que la hoja pueda decir quien agendo cada evento sin adivinarlo -- y para
  // que se distinga de un vistazo de las que aparto el bot.
  if (!f.origen_actual && ACEPTADAS.has(r.resultado)) {
    data.push({ range: `Reservas!G${r.fila}`, values: [['Confirmación humana']] });
  }
}

if (!data.length) return [];
return [{ json: { data, celdas: data.length } }];

// Las fechas que ACABAN de entrar en la agenda, para bloquearlas tambien en el
// Google Calendar que abre el asesor.
//
// Solo las nuevas: una que ya estaba no tiene por que crear el evento otra
// vez. En la corrida normal esto devuelve cero items y la rama entera no se
// ejecuta, que es justo lo que se quiere -- ni una llamada a Google cada
// quince minutos por unas fechas que no han cambiado.
//
// El `pairedItem` va a mano y no es adorno: un nodo Code en modo
// runOnceForAllItems no puede saber de que item de entrada sale cada uno de
// salida, asi que n8n no lo rellena solo. Sin el, la expresion de aguas abajo
// que mira a este nodo se queda sin de donde agarrarse y el
// id del evento no vuelve a la base -- callado, porque ese nodo continua en
// error a proposito. El nodo que lo necesita es `Guardar Event ID`.
const salida = [];
$('Sincronizar').all().forEach((item, i) => {
  if (item.json.resultado === 'nueva') salida.push({ json: item.json, pairedItem: { item: i } });
});
return salida;

